setTimeout(function () {
  if (document.querySelector('.dj-promo')) return;
  var b = document.createElement('div');
  b.className = 'dj-promo';
  b.textContent = 'New: evening appointments on Thursdays until 9pm.';
  var h = document.querySelector('.site-header');
  if (h) h.after(b);
}, 1200);
